[
  {
    "ce_mental_state_attribution": "guess is the others are frozen",
    "ce_contextual_explanation": "hoping someone else will speak first",
    "sys_consequence_reasoning": "one life lost set against the very real chance of losing more"
  },
  {
    "ce_mental_state_attribution": "group wants something that feels fair",
    "ce_contextual_explanation": "a draw gives everyone an even shot they can live with",
    "sys_fairness_reciprocity": "a draw gives everyone an even shot",
    "sys_consequence_reasoning": "a fast lottery handles both"
  },
  {
    "ae_welfare_concern": "My survival matters, just not more than getting five people off",
    "ce_mental_state_attribution": "sense a couple of people are close to panic",
    "sys_consequence_reasoning": "just not more than getting five people off that island"
  },
  {
    "ce_mental_state_attribution": "someone looks torn about offering",
    "sys_rule_justification": "Choice versus pressure is the line I care about most"
  },
  {
    "ce_mental_state_attribution": "expect the others to carry some guilt",
    "ce_supportive_use": "make my decision loud and final and ask them to go",
    "sys_consequence_reasoning": "One loss instead of risking six is simple enough"
  },
  {
    "ce_mental_state_attribution": "anyone else is already leaning toward staying",
    "sys_rule_justification": "Respecting other people's choices matters"
  },
  {
    "ce_mental_state_attribution": "they'd want that choice treated as real",
    "sys_rule_justification": "I don't think I'm obliged to hand over my life"
  },
  {
    "ce_mental_state_attribution": "I think the others are scared of being the one chosen",
    "ce_supportive_use": "my volunteering takes that fear off all five at once",
    "sys_consequence_reasoning": "My life for five certain rescues is a price I'd pay"
  },
  {
    "ce_mental_state_attribution": "suspect we're all thinking, that nobody wants to be the person",
    "ce_supportive_use": "Naming it plainly clears the air so we can act",
    "sys_fairness_reciprocity": "A burden shared fairly"
  },
  {
    "ce_mental_state_attribution": "person privately feels they ought to offer and is dreading it",
    "ce_supportive_use": "going first spares them that",
    "sys_consequence_reasoning": "My life against five people out and gone fast"
  }
]
